        Ok(match_) => {
            let id = *match_.value;
            let captured_params: Vec<(String, String)> = match_
                .params
                .iter()
                .map(|(key, value)| (key.to_owned(), value.to_owned()))
                .collect();

            #[cfg(feature = "matched-path")]
            {
                use crate::extract::matched_path::{MatchedNestedPath, MatchedPath};

                if let Some(matched_path) = self.node.route_id_to_path.get(&id) {
                    let previous_path =
