                    } else {
                        None
                    };

                let resolved_path = if let Some(previous) = previous_path {
                    let previous = if let Some(stripped) =
                        previous.strip_suffix(NEST_TAIL_PARAM_CAPTURE)
                    {
                        stripped.to_owned()
                    } else {
